// proximaOrdemLocal alterna entre crescente e decrescente da coluna ("chave" e "chave_desc").
func proximaOrdemLocal(atual, chave string) string {
	if atual == chave {
		return chave + "_desc"
	}
	return chave
}

func setaOrdemLocal(atual, chave string) string {
	switch atual {
	case chave:
		return " ▲"
	case chave + "_desc":
		return " ▼"
	}
	return ""
}

